mapper.select:
SELECT o.id, o.order_no, o.user_id, o.screening_id, o.movie_id, o.cinema_id, o.status, o.total_amount, o.pay_expire_time, o.pay_time, o.ticket_code, o.cancel_reason, o.create_time, m.title AS movie_title, m.poster AS movie_poster, c.name AS cinema_name, h.name AS hall_name, s.start_time FROM t_order o JOIN t_movie m ON o.movie_id = m.id JOIN t_cinema c ON o.cinema_id = c.id JOIN t_screening s ON o.screening_id = s.id JOIN t_hall h ON s.hall_id = h.id WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.id DESC
